import{_ as l,C as t,o as n,c as r,a3 as e,b as d,w as i,a as o,E as h,a4 as m}from"./chunks/framework.BvvarXmc.js";const u="/screenshots/pindah-kelas.png",K=JSON.parse('{"title":"Pindah Kelas & Kenaikan Kelas","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-admin/pindah-kelas.md","filePath":"panduan-admin/pindah-kelas.md","lastUpdated":null}'),k={name:"panduan-admin/pindah-kelas.md"};function p(g,a,P,c,b,_){const s=t("Mermaid");return n(),r("div",null,[a[1]||(a[1]=e('<h1 id="pindah-kelas-kenaikan-kelas" tabindex="-1">Pindah Kelas &amp; Kenaikan Kelas <a class="header-anchor" href="#pindah-kelas-kenaikan-kelas" aria-label="Permalink to &quot;Pindah Kelas &amp; Kenaikan Kelas&quot;">​</a></h1><p>Fitur <strong>Pindah Kelas</strong> digunakan oleh staf Tata Usaha untuk mengelola mutasi rombel siswa dalam satu tingkat, kenaikan kelas massal antar-tingkat di akhir tahun ajaran, serta melacak riwayat historis mutasi siswa.</p><hr><h2 id="tampilan-halaman-pindah-kelas" tabindex="-1">Tampilan Halaman Pindah Kelas <a class="header-anchor" href="#tampilan-halaman-pindah-kelas" aria-label="Permalink to &quot;Tampilan Halaman Pindah Kelas&quot;">​</a></h2><p><img src="'+u+'" alt="Pindah Kelas"></p><hr><h2 id="_1-dua-mode-perpindahan-siswa" tabindex="-1">1. Dua Mode Perpindahan Siswa <a class="header-anchor" href="#_1-dua-mode-perpindahan-siswa" aria-label="Permalink to &quot;1. Dua Mode Perpindahan Siswa&quot;">​</a></h2><p>Aplikasi menyediakan dua skenario pemindahan kelas:</p><ol><li><strong>Pindah Kelas Biasa (Reguler)</strong>: Memindahkan satu atau beberapa siswa ke rombel lain dalam tingkatan yang sama (contoh: dari <em>Kelas 7A</em> ke <em>Kelas 7B</em>).</li><li><strong>Kenaikan Kelas (Massal / Opsi Acak)</strong>: Memindahkan seluruh siswa yang lulus tingkat ke kelas tingkat berikutnya di tahun ajaran baru (contoh: seluruh siswa <em>Kelas 7</em> naik ke <em>Kelas 8</em>).</li></ol><hr><h2 id="_2-langkah-langkah-memindahkan-siswa-pindah-biasa" tabindex="-1">2. Langkah-Langkah Memindahkan Siswa (Pindah Biasa) <a class="header-anchor" href="#_2-langkah-langkah-memindahkan-siswa-pindah-biasa" aria-label="Permalink to &quot;2. Langkah-Langkah Memindahkan Siswa (Pindah Biasa)&quot;">​</a></h2>',11)),(n(),d(m,null,{default:i(()=>[h(s,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20Pilih%20Kelas%20Asal%22%5D%20--%3E%20B%5B%222.%20Centang%20Siswa%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Pilih%20Kelas%20Tujuan%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Masukkan%20Alasan%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20Klik%20'Proses%20Pindah'%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22Siswa%20Resmi%20Berpindah%20Rombel%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="panduan-operasional" tabindex="-1">Panduan Operasional: <a class="header-anchor" href="#panduan-operasional" aria-label="Permalink to &quot;Panduan Operasional:&quot;">​</a></h3><ol><li>Buka menu <strong>Data Master</strong> <strong>Pindah Kelas</strong> submenu <strong>Proses Pindah</strong>.</li><li><strong>Pilih Kelas Asal</strong>: Tentukan rombel asal siswa yang akan dipindahkan.</li><li>Tabel akan menampilkan seluruh daftar siswa di kelas tersebut: <ul><li>Beri tanda centang pada satu atau beberapa siswa yang akan dipindah.</li></ul></li><li><strong>Pilih Kelas Tujuan</strong>: Tentukan rombel baru bagi siswa terpilih.</li><li><strong>Alasan Pindah Kelas</strong> <em>(Opsional)</em>: Tuliskan keterangan singkat perpindahan (contoh: <em>Permohonan orang tua / Penyesuaian minat jurusan</em>).</li><li>Klik tombol <strong><code>Proses Pindah Kelas</code></strong>.</li><li>Sistem otomatis memperbarui data rombel siswa, memindahkan absensi ke kelas baru, dan mencatat log perpindahan.</li></ol><hr><h2 id="_3-melihat-riwayat-perpindahan-siswa" tabindex="-1">3. Melihat Riwayat Perpindahan Siswa <a class="header-anchor" href="#_3-melihat-riwayat-perpindahan-siswa" aria-label="Permalink to &quot;3. Melihat Riwayat Perpindahan Siswa&quot;">​</a></h2><p>Untuk kebutuhan audit dan buku induk:</p><ol><li>Buka submenu <strong>Riwayat Pindah</strong> (<code>/manage/students/class-transfer/history</code>).</li><li>Anda dapat melihat: <ul><li>Nama Lengkap &amp; NISN Siswa.</li><li>Kelas Lama Kelas Baru.</li><li>Tanggal dan Jam Perpindahan.</li><li>Petugas TU / Admin yang memproses.</li><li>Keterangan alasan perpindahan.</li></ul></li><li>Anda dapat mencetak atau mengekspor riwayat mutasi ini ke format Excel.</li></ol>',6))])}const T=l(k,[["render",p]]);export{K as __pageData,T as default};
